<template>
  <section class="wrong-page" data-testid="student-wrong-book">
    <header class="wrong-header"><div class="wrong-header__title"><div class="wrong-icon">错</div><div><span class="eyebrow">复盘每一次错误</span><h1>错题本</h1><p>从真实答题记录中找到仍需理解的知识点。</p></div></div><div class="wrong-count"><strong>{{ wrongBook.data?.total ?? 0 }}</strong><span>道记录</span></div></header>
    <div v-if="wrongBook.state === 'LOADING' || wrongBook.state === 'INITIAL'" class="state-card">正在加载错题本...</div>
    <div v-else-if="wrongBook.state === 'ERROR'" class="state-card state-card--error"><h2>错题本数据加载失败</h2><p>{{ wrongBook.error }}</p><button type="button" @click="load">重试</button></div>
    <div v-else-if="wrongBook.state === 'EMPTY'" class="state-card"><h2>还没有错题</h2><p>完成练习并明确加入错题本后，这里会出现真实记录。</p><button type="button" @click="load">重新加载</button></div>
    <template v-else>
      <section class="filter-bar" aria-label="错题筛选"><div class="tabs" role="tablist"><button type="button" :class="{ active: activeTab === 'TO_REVIEW' }" role="tab" :aria-selected="activeTab === 'TO_REVIEW'" @click="activeTab = 'TO_REVIEW'">待复习 <span>{{ pendingCount }}</span></button><button type="button" :class="{ active: activeTab === 'ALL' }" role="tab" :aria-selected="activeTab === 'ALL'" @click="activeTab = 'ALL'">全部记录 <span>{{ wrongBook.data?.total ?? 0 }}</span></button><button type="button" :class="{ active: activeTab === 'MASTERED' }" role="tab" :aria-selected="activeTab === 'MASTERED'" @click="activeTab = 'MASTERED'">已掌握</button></div><label class="knowledge-filter">知识点 <select v-model="knowledgeFilter"><option value="ALL">全部</option><option v-for="option in knowledgePointOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label></section>
      <section class="summary-row"><article><span>待复习</span><strong>{{ pendingCount }}</strong></article><article><span>知识点</span><strong>{{ knowledgePoints.length }}</strong></article><article><span>已复习</span><strong>{{ reviewedCount }}</strong></article></section>
      <section class="wrong-workspace">
        <aside class="wrong-list"><div class="list-heading"><h2>错题记录</h2><span>{{ filteredItems.length }} 条</span></div><button v-for="(item, index) in filteredItems" :key="item.wrongItemId" type="button" class="wrong-item" :class="{ active: item.wrongItemId === wrongBook.selectedItem?.wrongItemId }" @click="wrongBook.select(item.wrongItemId)"><span class="wrong-item__index">题目 {{ index + 1 }}</span><span class="wrong-item__body"><strong>{{ item.knowledgePointLabel }}</strong><small>{{ item.questionSummary }} · {{ item.reasonLabel }}</small></span><em :class="item.status.toLowerCase()">{{ item.statusLabel }}</em></button><div v-if="!filteredItems.length" class="list-empty">没有匹配的错题</div></aside>
        <main v-if="selectedItem" class="wrong-detail"><header class="detail-header"><div><span class="question-index">错题记录</span><h2>{{ selectedItem.knowledgePointLabel }}</h2></div><span>{{ selectedItem.reviewCount }} 次复习</span></header><p class="detail-description">{{ selectedItem.questionSummary }}</p><section class="evidence-grid"><div><span>错误原因</span><strong>{{ selectedItem.reasonLabel }}</strong></div><div><span>当前状态</span><strong>{{ selectedItem.statusLabel }}</strong></div><div><span>加入时间</span><strong>{{ formatDate(selectedItem.addedAt) }}</strong></div></section><section class="review-panel"><div><span class="eyebrow">再次作答</span><h3>用自己的答案验证理解</h3><p>后端会根据原题答案判定本次复习结果。</p></div><form @submit.prevent="review"><input v-model="reviewAnswer" required placeholder="输入你的答案" aria-label="错题复习答案" /><button type="submit" :disabled="wrongBook.reviewing">提交复习</button></form><p v-if="wrongBook.actionFeedback" class="action-feedback">{{ wrongBook.actionFeedback }}</p></section><button type="button" class="coach-link" @click="discussWithCoach">和 AI 教练讨论这个知识点 <span>›</span></button></main>
        <aside v-else class="wrong-detail wrong-detail--empty"><h2>选择一道错题</h2><p>从左侧列表查看错误原因与复习操作。</p></aside>
      </section>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useWrongBookStore } from '@/stores/wrongBookStore'
import { useCoachStore } from '@/stores/coachStore'
const router = useRouter(); const wrongBook = useWrongBookStore(); const activeTab = ref<'TO_REVIEW' | 'ALL' | 'MASTERED'>('TO_REVIEW'); const knowledgeFilter = ref('ALL'); const reviewAnswer = ref('')
const coach = useCoachStore()
const items = computed(() => wrongBook.items); const pendingCount = computed(() => items.value.filter((item) => item.status === 'TO_REVIEW').length); const reviewedCount = computed(() => items.value.filter((item) => item.reviewCount > 0).length); const knowledgePoints = computed(() => [...new Set(items.value.map((item) => item.knowledgePointId))]); const knowledgePointOptions = computed(() => [...new Map(items.value.map((item) => [item.knowledgePointId, { value: item.knowledgePointId, label: item.knowledgePointLabel }])).values()]); const filteredItems = computed(() => items.value.filter((item) => (activeTab.value === 'ALL' || item.status === activeTab.value) && (knowledgeFilter.value === 'ALL' || item.knowledgePointId === knowledgeFilter.value))); const selectedItem = computed(() => filteredItems.value.find((item) => item.wrongItemId === wrongBook.selectedWrongItemId) ?? filteredItems.value[0] ?? null)
const formatDate = (value: string) => new Intl.DateTimeFormat('zh-CN', { month: 'numeric', day: 'numeric' }).format(new Date(value))
async function load() { await wrongBook.load(true) }
async function review() { if (!reviewAnswer.value.trim()) return; const result = await wrongBook.review(reviewAnswer.value.trim()); if (result?.correct) reviewAnswer.value = '' }
function discussWithCoach() {
  if (!selectedItem.value) return
  coach.setWrongBookContext({
    knowledgePointName: selectedItem.value.knowledgePointLabel,
    wrongBookReason: selectedItem.value.reasonLabel,
    reviewStatus: selectedItem.value.statusLabel,
    questionStem: selectedItem.value.questionSummary,
  })
  void router.push('/student/ai-coach')
}
onMounted(() => void load())
</script>

